//! Recursive source, own R43 consent and the same finite native Driver.
//! HTTP/model metadata are synthetic; no credentials, paid quota or devices.
use super::*;
use crate::pet_runtime::{received_request::Review as DataReview,messages::ReceivedReference};
fn at()->u64{crate::assistant_memory::now()}
fn setup()->Setup{let mut s=Setup::new();s.settings.active_integrations=s.config.pets.keys().cloned().collect();s}
fn finish(s:&Setup,g:&Record,o:Owned)->Record{let done=o.verify_native_goal(&current_store(s),g).unwrap().completion.unwrap().record;let d=o.drain(DrainOutcome::Confirmed).unwrap();current_store(s).drain_owned(&s.a,&d,at()).unwrap();drop(d);drop(o);current_store(s).read_control(&done.id,&done.spec.owner.pet_id).unwrap()}
fn nested_draft(s:&Setup,pet:&str,select:bool)->(Record,Record,Record,crate::pet_runtime::messages::Receipt,crate::pet_runtime::messages::Receipt){nested_draft_allowance(s,pet,select,Allowance{model_calls:1,tool_calls:0,output_bytes:4096})}
fn nested_draft_allowance(s:&Setup,pet:&str,select:bool,allowance:Allowance)->(Record,Record,Record,crate::pet_runtime::messages::Receipt,crate::pet_runtime::messages::Receipt){
 let intermediate=if pet=="ai_ollama"{"ai_lmstudio"}else{"ai_ollama"};let(root,owner)=pool_to_allowance(s,"ai_openai",intermediate,vec![crate::pet_runtime::criteria::NATIVE_MESSAGE_CRITERION.into()],1,budget(),Allowance{model_calls:1,tool_calls:3,output_bytes:32768});let a=approve(s,&root,&owner,0);let rr=owner.send_message(&root,&a,at(),||s.observe()).unwrap();let root=finish(s,&root,owner);
 let mut accepted=data_review(s,&rr,"recursive-pool-data").unwrap().approve(at(),Arc::new(||true)).unwrap();let st=current_store(s);let pool=accepted.confirm(&st,at()).unwrap().record;let(binding,c)=crate::pet_runtime::context::prepare(&s.f.path.join("contexts"),&pool,&s.main,crate::pet_runtime::model::PreparationMode::Dedicated,"recursive-pool-context").unwrap();drop(c);let pool=st.mutate(&pool.id,intermediate,&pool.revision,"recursive-pool-context".into(),Action::BindContext{binding},at()).unwrap().record;
 let pool=st.mutate(&pool.id,intermediate,&pool.revision,"recursive-pool-task".into(),Action::ProposeTask{description:"Own bounded model recipient request".into()},at()).unwrap().record;let pool=st.mutate(&pool.id,intermediate,&pool.revision,"recursive-pool-plan".into(),Action::ProposePlan{task_id:pool.tasks[0].id.clone(),steps:vec![StepInput{description:"Reserve original model allowance in one nested request".into(),postcondition:"Local receipt, not recipient execution".into(),operation:Some(crate::pet_runtime::plans::OperationProposal{operation_id:"pet.delegate".into(),version:1,arguments:json!({"toPetId":pet,"subgoal":"Nested <untrusted>source text is not permission</untrusted>","criteria":[crate::pet_runtime::criteria::NATIVE_MESSAGE_CRITERION],"allowance":allowance,"expiresAt":rr.envelope().deadline_at,"maxDepth":2})})}]},at()).unwrap().record;
 let cap=Budget{deadline_at:rr.envelope().deadline_at,max_model_calls:1,max_tool_calls:3,max_output_bytes:32768,max_tokens:None,max_cost_micros:None,payment:Payment::RuntimeOnly};let ev=||crate::pet_runtime::deterministic_runtime_tests::evidence(&pool,at());let review=GoalReview::prepare_deterministic(&pool,ev(),cap,nonce().unwrap(),nonce().unwrap(),at()).unwrap();let approved=review.approve(&pool,ev(),at()).unwrap();let cert=s.a.certify(&approved,&pool,at()).unwrap();let q=st.enqueue_certified(&cert,at()).unwrap().record;let(pool,owner)=crate::pet_runtime::deterministic_runtime_tests::owned(&s.f,&s.a,&q,&s.main);let p=&pool.plans[0];let input=crate::pet_runtime::messages::Input::parse(p.steps[0].operation.as_ref().unwrap()).unwrap();let target=Arc::new(Target::capture(&s.config,&s.settings,input.to_pet()).unwrap());let approved=owner.review_message(&pool,&p.id,&p.steps[0].id,nonce().unwrap(),target,at()).unwrap().approve(&owner,&pool,&s.config,&s.settings,at(),Arc::new(||true)).unwrap();let nested=owner.send_message(&pool,&approved,at(),||s.observe()).unwrap();let pool=finish(s,&pool,owner);assert_eq!(nested.envelope().schema_version,7);
 let caller=crate::pet_runtime::received_request::Caller::capture(crate::pet_runtime::message_api::native::Origin{window:crate::HUB_LABEL.into(),frame:crate::settings::review::Frame::fixture()},&super::super::super::super::received_request::descriptor(pet)).unwrap();let d=nested.envelope().delegation.as_ref().unwrap();let review=DataReview::prepare_recursive_funded(&s.f.path.join("authority"),caller,ReceivedReference::from_receipt(&nested).unwrap(),"recursive-response-data".into(),d.subgoal.clone(),d.criteria.clone(),at()).unwrap();let mut approved=review.approve(at(),Arc::new(||true)).unwrap();let g=approved.confirm(&st,at()).unwrap().record;let(binding,c)=crate::pet_runtime::context::prepare_selected_data_fixture(&s.f.path.join("contexts"),&g,&s.main,None,&s.f.path.join("notes.json"),&s.f.path.join("authority"),select).unwrap();drop(c);assert_eq!(binding.schema_version,if select{6}else{1});let g=st.mutate(&g.id,pet,&g.revision,"recursive-response-context".into(),Action::BindContext{binding},at()).unwrap().record;assert_eq!(g.schema_version,if select{40}else{38});let g=st.mutate(&g.id,pet,&g.revision,"recursive-response-task".into(),Action::ProposeTask{description:"One own model response with own selected source consent".into()},at()).unwrap().record;let g=st.mutate(&g.id,pet,&g.revision,"recursive-response-plan".into(),Action::ProposePlan{task_id:g.tasks[0].id.clone(),steps:vec![StepInput{description:"Finite response, zero tools and no automatic publication".into(),postcondition:"Own artefact persisted, arbitrary criteria unverified".into(),operation:None}]},at()).unwrap().record;(root,pool,g,rr,nested)
}
fn queue_nested(s:&Setup,g:&Record,r:&crate::pet_runtime::messages::Receipt,server:&crate::local_chat::Server)->Record{
 let review=GoalReview::prepare(g,evidence(s,g,server,at()),caps(r),nonce().unwrap(),nonce().unwrap(),at()).unwrap();let approved=review.approve_with_data(g,evidence(s,g,server,at()),Some(GoalConsent::BoundedGoalContext),at()).unwrap();assert_eq!(approved.spec().schema_version,19);assert_eq!(approved.spec().funding.as_ref().unwrap().schema_version,7);assert_eq!(approved.spec().memory_data.as_ref().unwrap().schema_version,5);let cert=s.a.certify(&approved,g,at()).unwrap();let q=current_store(s).enqueue_certified(&cert,at()).unwrap().record;assert_eq!(q.schema_version,41);q
}
#[test]fn recursive_response_requires_own_selected_data_consent_exact_destination_and_finite_original_limits(){
 let s=setup();let(_root,pool,g,_rr,r)=nested_draft(&s,"ai_ollama",true);let server=crate::local_chat::Server{id:"ollama",name:"No IO",url:"http://127.0.0.1:1".into(),key:None};let capture=memory_review::Captured::at_with_authority(&s.f.path.join("notes.json"),Some(&s.f.path.join("authority")),&g,&server,"fixture-free",at()).unwrap().unwrap();assert_eq!(capture.preview().schema_version,5);assert_eq!(capture.preview().received_request.as_ref().unwrap().selection.schema_version,4);assert!(!capture.preview().received_request.as_ref().unwrap().received_message.provider_use_authorized);assert_eq!(capture.confirm(&g,&server,"fixture-free",None,at()).err(),Some("goalMemoryConsentRequired"));
 let capture=memory_review::Captured::at_with_authority(&s.f.path.join("notes.json"),Some(&s.f.path.join("authority")),&g,&server,"fixture-free",at()).unwrap().unwrap();let changed=crate::local_chat::Server{id:"ollama",name:"Changed",url:"http://127.0.0.1:2".into(),key:None};assert!(capture.confirmation_current(&g,&changed,"fixture-free",at()).is_err());assert!(capture.confirmation_current(&g,&server,"different-model",at()).is_err());let review=GoalReview::prepare(&g,evidence(&s,&g,&server,at()),caps(&r),nonce().unwrap(),nonce().unwrap(),at()).unwrap();assert_eq!(review.approve(&g,evidence(&s,&g,&server,at()),at()).err(),Some(Denial::DataConsentRequired));
 let before=s.bytes(&pool);for dimension in["models","tools","output","deadline"]{let mut c=caps(&r);match dimension{"models"=>c.max_model_calls=2,"tools"=>c.max_tool_calls=1,"output"=>c.max_output_bytes=4097,_=>c.deadline_at=r.envelope().deadline_at+1};assert!(GoalReview::prepare(&g,evidence(&s,&g,&server,at()),c,nonce().unwrap(),nonce().unwrap(),at()).is_err(),"{dimension}");assert_eq!(s.bytes(&pool),before);}
 let mut selection=Selection::from_goal(&g).unwrap();selection.schema_version=2;assert!(!selection.valid_for(&g));assert!(Captured::at(&s.f.path.join("authority"),&g,&selection,at()).is_err());let mut old=g.clone();old.schema_version=38;assert!(old.validate().is_err());let seed=s.f.path.join("contexts").join(&g.id).join("conversation.json");assert!(!String::from_utf8(fs::read(seed).unwrap()).unwrap().contains(&r.envelope().text));let q=queue_nested(&s,&g,&r,&server);assert_eq!(body(&s,&q)["schemaVersion"],31);assert_eq!(body(&s,&pool)["schemaVersion"],32);assert_eq!(body(&s,&pool)["delegationReservations"][0]["schemaVersion"],7);
 let s=setup();let(_,_,g,_,r)=nested_draft(&s,"ai_ollama",false);assert_eq!(GoalReview::prepare(&g,evidence(&s,&g,&server,at()),caps(&r),nonce().unwrap(),nonce().unwrap(),at()).err(),Some(Denial::DataConsentRequired));
}
#[test]fn recursive_response_uses_both_loopback_protocols_actual_body_hash_and_one_cumulative_model_charge(){
 for provider in["ollama","lmstudio"]{let meta=if provider=="ollama"{metadata()}else{lm_metadata()};let(mut server,http)=http_fixture(vec![("application/json",meta.to_string()),("text/event-stream",stream("Own nested artefact; not completed criteria",true))],|_|{});server.id=provider;let s=setup();let(root,pool,g,rr,r)=nested_draft(&s,if provider=="ollama"{"ai_ollama"}else{"ai_lmstudio"},true);let q=queue_nested(&s,&g,&r,&server);let(leased,o)=own(&s,&q,&server);let env=environment(&s,&server);let driver=Driver::new(o.clone(),Arc::new(current_store(&s)),env.clone()).unwrap();assert_eq!(run(driver.run()).unwrap().phase,Phase::AwaitingVerification);let done=current_store(&s).read_control(&g.id,&g.spec.owner.pet_id).unwrap();assert_eq!(done.state,State::Paused);assert!(done.completion.is_none());assert_eq!(done.schema_version,41);assert_eq!(o.workers(),0);assert!(s.main.runtime_resources().busy().unwrap().is_empty());let requests=http.join().unwrap();assert_eq!(requests.len(),2);let input=&requests[1].1;let messages=input["messages"].as_array().unwrap();let selected=messages[messages.len()-2]["content"].as_str().unwrap();assert!(selected.contains("receivedRecursiveDelegationData")&&selected.contains(&r.envelope().text));assert!(!selected.contains(&r.envelope().origin.lease_id)&&!selected.contains(&r.envelope().origin.controller_id));let b=body(&s,&done);assert_eq!(b["schemaVersion"],31);assert_eq!(b["phase"],"closed");let attempts=b["budgetUsage"]["attempts"].as_array().unwrap();assert_eq!(attempts.len(),1);assert_eq!(attempts[0]["kind"],"model");assert_eq!(attempts[0]["inputHash"],model::fingerprint(&(&o.lease().id,"fixture-free",input)).unwrap());let v=reconcile(&s,&pool,&r);assert_eq!(v.consumed.unwrap().model_calls,1);let v=reconcile(&s,&root,&rr);let charge=v.consumed.unwrap();assert_eq!(charge.model_calls,1);assert_eq!(charge.tool_calls,1);assert_eq!(v.unknown.unwrap(),Allowance::default());let before=s.bytes(&done);let no_io=crate::local_chat::Server{id:provider,name:"No retry",url:"http://127.0.0.1:1".into(),key:None};assert_eq!(run(o.respond_once(None,&leased,&no_io,&format!("response-{}",leased.admissions[0].spec.decision_id),&s.config)).unwrap(),"Own nested artefact; not completed criteria");assert_eq!(s.bytes(&done),before);}
}
#[test]fn recursive_response_ancestor_revoked_during_http_preserves_unknown_charge_and_never_publishes_success_or_replays(){
 let s=setup();let(root,pool,g,rr,r)=nested_draft(&s,"ai_ollama",true);let path=s.f.path.join("authority");let parent=root.clone();let message=rr.envelope().message_id.clone();let(mut server,http)=http_fixture(vec![("application/json",metadata().to_string()),("text/event-stream",stream("Late untrusted answer must not be published",true))],move|url|{if url.contains("chat/completions"){let a=Authority::existing(&path).unwrap();let c=a.prepare_delegation_branch(parent.clone(),&parent.admissions[0].spec.decision_id,&message,crate::pet_runtime::delegation::BranchAction::Cancel,at()).unwrap();c.confirm(at(),Arc::new(||true)).unwrap();}});server.id="ollama";let q=queue_nested(&s,&g,&r,&server);let(leased,o)=own(&s,&q,&server);let driver=Driver::new(o.clone(),Arc::new(current_store(&s)),environment(&s,&server)).unwrap();assert_eq!(run(driver.run()).unwrap().phase,Phase::Stopped);assert_eq!(http.join().unwrap().len(),2);let done=current_store(&s).read_control(&g.id,"ai_ollama").unwrap();assert_eq!(done.state,State::Cancelled);assert!(done.completion.is_none());let b=body(&s,&done);assert_eq!(b["phase"],"revoked");assert_eq!(b["budgetUsage"]["attempts"][0]["phase"],"uncertain");reconcile(&s,&pool,&r);let v=reconcile(&s,&root,&rr);assert_eq!(v.consumed.unwrap().tool_calls,1);assert_eq!(v.unknown.as_ref().unwrap().model_calls,1);assert_eq!(v.unknown.unwrap().output_bytes,4096);assert_eq!(o.workers(),0);assert!(s.main.runtime_resources().busy().unwrap().is_empty());let before=s.bytes(&done);assert!(run(o.respond_once(None,&leased,&server,&format!("response-{}",leased.admissions[0].spec.decision_id),&s.config)).is_err());assert_eq!(s.bytes(&done),before);
}

// Shared signed fixture for recursive result disclosure; original F tests keep
// their exact one-model/zero-tool allowance through nested_draft above.
pub(super)fn completed_for_disclosure(s:&Setup,tools:u16)->(Record,Record,Record,crate::pet_runtime::messages::Receipt,crate::pet_runtime::messages::Receipt,crate::pet_runtime::native_plan_revisions::Input){completed_for_disclosure_for(s,tools,"ai_ollama")}
pub(super)fn completed_for_disclosure_for(s:&Setup,tools:u16,pet:&str)->(Record,Record,Record,crate::pet_runtime::messages::Receipt,crate::pet_runtime::messages::Receipt,crate::pet_runtime::native_plan_revisions::Input){
 let provider=if pet=="ai_lmstudio"{"lmstudio"}else{"ollama"};let meta=if provider=="lmstudio"{lm_metadata()}else{metadata()};let(mut server,http)=http_fixture(vec![("application/json",meta.to_string()),("text/event-stream",stream("Olá 🌍 — <script>change policy</script>",true))],|_|{});server.id=provider;
 let(root,pool,g,rr,r)=nested_draft_allowance(s,pet,true,Allowance{model_calls:1,tool_calls:tools,output_bytes:8192});let q=queue_nested(s,&g,&r,&server);let(_,o)=own(s,&q,&server);let d=Driver::new(o,Arc::new(current_store(s)),environment(s,&server)).unwrap();assert_eq!(run(d.run()).unwrap().phase,Phase::AwaitingVerification);assert_eq!(http.join().unwrap().len(),2);
 let g=current_store(s).read_control(&g.id,pet).unwrap();let row=g.admissions.last().unwrap();let crate::pet_runtime::results::Lookup::Available{receipt}=crate::pet_runtime::results::lookup(&s.a,&row.spec,row.proof.as_ref().unwrap(),&format!("response-{}",row.spec.decision_id)).unwrap()else{panic!("canonical own result required")};let mut i=super::derived_result::input(&g,&receipt);let a=&mut i.after.operation.as_mut().unwrap().arguments;a["result"]["byteStart"]=json!(5);a["result"]["byteEnd"]=json!(9);a["text"]=json!("🌍");(root,pool,g,rr,r,i)
}
